citation(eu_reg_2024_1774_art_22, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 22, first subparagraph (lead words: ICT-related incident policy) and second subparagraph (secure retention of the evidence of point (d))', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'financial entities shall develop, document, and implement an ICT-related incident policy']).
citation(eu_reg_2024_1774_art_22_a, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 22, point (a) (documentation of the ICT-related incident management process)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'document the ICT-related incident management process referred to in Article 17 of Regulation (EU) 2022/2554']).
citation(eu_reg_2024_1774_art_22_b, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 22, point (b), with points (i) to (iii) (list of relevant internal and external contacts)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'establish a list of relevant contacts with internal functions and external stakeholders that are directly involved in ICT operations security']).
citation(eu_reg_2024_1774_art_22_c, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 22, point (c) (technical, organisational and operational incident management mechanisms)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'establish, implement, and operate technical, organisational, and operational mechanisms to support the ICT-related incident management process']).
citation(eu_reg_2024_1774_art_22_d, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 22, point (d) (retention of incident evidence for no longer than necessary)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'retain all evidence relating to ICT-related incidents for a period that shall be no longer than necessary for the purposes for which the data are collected']).
citation(eu_reg_2024_1774_art_22_e, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 22, point (e) (analysis of significant or recurring incidents and patterns)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'establish and implement mechanisms to analyse significant or recurring ICT-related incidents and patterns in the number and the occurrence of ICT-related incidents']).
citation(eu_reg_2024_1774_art_23_1, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 23(1) (roles and responsibilities for detection and response)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'Financial entities shall set clear roles and responsibilities to effectively detect and respond to ICT-related incidents and anomalous activities.']).
citation(eu_reg_2024_1774_art_23_2, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 23(2), second subparagraph (automated alerts on the completeness and integrity of data sources or log collection)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'the tools referred to in that point shall contain the tools that provide automated alerts based on pre-defined rules to identify anomalies affecting the completeness and integrity of the data sources or log collection']).
citation(eu_reg_2024_1774_art_23_2_a, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 23(2), first subparagraph, point (a), with points (i) to (iii) (collection, monitoring and analysis of factors, threats and provider incident notifications)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'collect, monitor, and analyse all of the following']).
citation(eu_reg_2024_1774_art_23_2_b, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 23(2), first subparagraph, point (b) (identification of anomalous activities and alerting tools)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'identify anomalous activities and behaviour, and implement tools generating alerts for anomalous activities and behaviour']).
citation(eu_reg_2024_1774_art_23_2_c, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 23(2), first subparagraph, point (c) (prioritisation of alerts within the expected resolution time)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'prioritise the alerts referred to in point (b) to allow for the management of the detected ICT-related incidents within the expected resolution time']).
citation(eu_reg_2024_1774_art_23_2_d, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 23(2), first subparagraph, point (d) (recording, analysis and evaluation of information on anomalous activities)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'record, analyse, and evaluate any relevant information on all anomalous activities and behaviours automatically or manually']).
citation(eu_reg_2024_1774_art_23_3, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 23(3) (protection of recordings of anomalous activities)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'Financial entities shall protect any recording of the anomalous activities against tampering and unauthorised access at rest, in transit and, where relevant, in use.']).
citation(eu_reg_2024_1774_art_23_4, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 23(4), with points (a) to (c) (logging of each detected anomalous activity)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'Financial entities shall log all relevant information for each detected anomalous activity']).
citation(eu_reg_2024_1774_art_23_5, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 23(5), with points (a) to (d) (criteria triggering incident detection and response)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'Financial entities shall consider all of the following criteria to trigger the ICT-related incident detection and response processes']).
citation(eu_reg_2024_1774_art_23_6, [label - 'Commission Delegated Regulation (EU) 2024/1774 Art 23(6) (criticality of the services affected)', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'financial entities shall also consider the criticality of the services affected']).
citation(eu_reg_2022_2554_art_16_1, [label - 'Regulation (EU) 2022/2554 (DORA) Art 16(1), first subparagraph (entities to which Articles 5 to 15 do not apply)', ref - 'https://eur-lex.europa.eu/eli/reg/2022/2554/oj', verbatim - 'Articles 5 to 15 of this Regulation shall not apply to small and non-interconnected investment firms']).

